import { LOGO_EYE, LOGO_FIELD, LOGO_HALO, LOGO_NEEDLE, LOGO_SWOOSH, LOGO_T, LOGO_VIEWBOX } from "@/lib/logo-geometry";

/**
 * The Threadcore mark: a slanted "T" with a needle and an orange thread loop.
 * Geometry is generated by scripts/build-logo.py from the supplied artwork.
 * The gaps where the thread and needle cross the T are true knock-outs (masks),
 * so the mark sits cleanly on any background.
 */
export function LogoMark({
  className,
  tone = "dark",
}: {
  className?: string;
  /** "dark" = for light backgrounds, "light" = for dark backgrounds. */
  tone?: "dark" | "light";
}) {
  const body = tone === "dark" ? "var(--ink)" : "#ffffff";
  const id = `lm-${tone}`;
  const maskBox = { maskUnits: "userSpaceOnUse" as const, x: 0, y: 0, width: LOGO_FIELD, height: LOGO_FIELD };
  const knock = { fill: "#000", stroke: "#000", strokeWidth: LOGO_HALO * 2, strokeLinejoin: "round" as const };
  return (
    <svg viewBox={LOGO_VIEWBOX} aria-hidden="true" className={className}>
      <defs>
        <mask id={`${id}-t`} {...maskBox}>
          <rect width={LOGO_FIELD} height={LOGO_FIELD} fill="#fff" />
          <path d={LOGO_SWOOSH} {...knock} />
          <path d={LOGO_NEEDLE} {...knock} />
        </mask>
        <mask id={`${id}-s`} {...maskBox}>
          <rect width={LOGO_FIELD} height={LOGO_FIELD} fill="#fff" />
          <path d={LOGO_NEEDLE} {...knock} />
        </mask>
      </defs>
      <path d={LOGO_T} fill={body} mask={`url(#${id}-t)`} />
      <path d={LOGO_SWOOSH} fill="var(--brand-orange)" mask={`url(#${id}-s)`} />
      <path d={LOGO_NEEDLE} fill="none" stroke={body} strokeWidth={5} strokeLinejoin="round" />
      <path d={LOGO_EYE} fill="none" stroke={body} strokeWidth={4.5} strokeLinejoin="round" />
    </svg>
  );
}
